 "content": "def transform(grid):
    """Extend colored 3-crosses along their row and column.

    Each ray passes its source cross's own 3 arm, then continues until another
    3 cell blocks it. Existing nonzero cells are preserved. Empty-cross centers
    mark a one-cell gap column in horizontal strokes. Vertical strokes are
    applied after horizontal strokes at intersections.
    """
    h, w = len(grid), len(grid[0])
    colored = []
    blank_centers = set()
    for r in range(h):
        for c in range(w):
            arms = ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))
            cross = all(0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 3
                        for rr, cc in arms)
            if cross:
                if grid[r][c] == 0:
                    blank_centers.add((r, c))
                elif grid[r][c] != 3:
                    colored.append((r, c, grid[r][c]))

    out = [row[:] for row in grid]
    gap_columns = {c for r, c in blank_centers}

    # Horizontal rays first.
    for r, c, color in colored:
        for dc in (-1, 1):
            cc = c + dc
            if 0 <= cc < w and grid[r][cc] == 3:  # source's own arm
                cc += dc
            while 0 <= cc < w:
                if grid[r][cc] == 3:
                    break
                if grid[r][cc] == 0 and cc not in gap_columns:
                    out[r][cc] = color
                cc += dc

    # Vertical rays overwrite horizontal colors at crossings.
    for r, c, color in colored:
        for dr in (-1, 1):
            rr = r + dr
            if 0 <= rr < h and grid[rr][c] == 3:  # source's own arm
                rr += dr
            while 0 <= rr < h:
                if grid[rr][c] == 3:
                    break
                if grid[rr][c] == 0:
                    out[rr][c] = color
                rr += dr
    return out


if __name__ == '__main__':
    # The task fixtures are exercised by the external validation harness.
    pass
